import{_ as i,C as r,o as n,c as s,j as d,a as e,E as o,a5 as c}from"./chunks/framework.BYIUCCsM.js";const S=JSON.parse('{"title":"排序","description":"","frontmatter":{},"headers":[],"relativePath":"components/sortable.md","filePath":"components/sortable.md","lastUpdated":1787863479000}'),h={name:"components/sortable.md"},b={id:"排序",tabindex:"-1"};function p(u,t,m,g,x,f){const l=r("Badge"),a=r("XhDemo");return n(),s("div",null,[d("h1",b,[t[0]||(t[0]=e("排序 ",-1)),o(l,{type:"info",text:"sortable"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#排序","aria-label":'Permalink to "排序 <Badge type="info" text="sortable" />"'},"​",-1))]),t[3]||(t[3]=c('<p>让用户拖着重排一列条目，键盘也能完成同一件事。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>顺序本身是数据的一部分：表格列的先后、标签页的排列、收藏项的次序。</li><li>顺序要存回后端：<code>sort</code> 事件直接给出重排好的 <code>ids</code>，接上就能提交。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>顺序由数据决定而不由人决定：那是排序规则，不是拖拽。</li><li>要把条目拖到<strong>另一个</strong>容器里：本组件只管单个列表内部的重排。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>ids</code> 是顺序的唯一真源，<code>sort</code> 事件回传的 <code>ids</code> 已经重排好，可以直接写回。</li><li>拖动过程走乐观投影：其余条目实时让位，松手即定，不是拖完才跳一下。</li><li>键盘路径默认开着且关不掉：空格拾起、方向键挪、空格放下、Esc 取消，全程有读屏播报。</li><li>按下之后要走够 <code>activationDistance</code>（默认 5px）才算拖动，因此条目本身仍然可以点击。</li><li>拖到容器边缘会自动滚动，视口外的落点够得着。</li><li><code>orientation</code> 三档：竖排、横排，以及换行网格用的 <code>both</code>——网格按最近中心判落点。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>ids 是顺序的唯一真源，sort 事件回传的 ids 已经重排好，可直接写回</p>',10)),o(a,{src:"sortable/01-basic"}),t[4]||(t[4]=d("h3",{id:"横排与网格",tabindex:"-1"},[e("横排与网格 "),d("a",{class:"header-anchor",href:"#横排与网格","aria-label":'Permalink to "横排与网格"'},"​")],-1)),t[5]||(t[5]=d("p",null,"orientation 三档：竖排、横排，换行网格用 both，落点按最近中心判",-1)),o(a,{src:"sortable/02-horizontal"}),t[6]||(t[6]=d("h3",{id:"键盘拖拽",tabindex:"-1"},[e("键盘拖拽 "),d("a",{class:"header-anchor",href:"#键盘拖拽","aria-label":'Permalink to "键盘拖拽"'},"​")],-1)),t[7]||(t[7]=d("p",null,"默认开着且关不掉：Tab 到手柄，空格拾起，方向键挪，空格放下，Esc 取消",-1)),o(a,{src:"sortable/03-keyboard"}),t[8]||(t[8]=d("h3",{id:"禁用",tabindex:"-1"},[e("禁用 "),d("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),t[9]||(t[9]=d("p",null,"手柄退出 Tab 序列，按下也不进拖动",-1)),o(a,{src:"sortable/04-disabled"}),t[10]||(t[10]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-sortable&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhSortableItem</code> <code>XhSortableItemHandle</code> <code>XhSortableLiveRegion</code> <code>XhSortableRoot</code></td></tr><tr><td>组合式函数</td><td><code>useSortable</code></td></tr><tr><td>状态机</td><td><code>sortableMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/sortable.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;sortable&quot;</code>：<strong><code>root</code></strong> · <strong><code>item</code></strong> · <code>item-handle</code> · <code>live-region</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>ids</code></td><td><code>string[]</code></td><td>是</td><td>项的稳定标识，数组顺序就是当前顺序。这是顺序的唯一真源。 DOM 里项的先后必须与它一致——几何按 DOM 量，回调按它算。</td></tr><tr><td><code>orientation</code></td><td><code>SortableAxis</code></td><td></td><td>排序沿哪根轴走。换行网格用 <code>both</code>。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>activationDistance</code></td><td><code>number</code></td><td></td><td>按下之后走多远才算开始拖，默认 5px。给 0 表示按下即拖。</td></tr><tr><td><code>autoScroll</code></td><td><code>boolean</code></td><td></td><td>拖到容器边缘时自动滚动，默认开。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td></td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;SortableTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onSort</code></td><td><code>(details: SortableSortDetails) =&gt; void</code></td><td></td><td>顺序变化意图。取消的那次不发。</td></tr><tr><td><code>onDragStart</code></td><td><code>(details: SortableDragStartDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onDragEnd</code></td><td><code>(details: SortableDragEndDetails) =&gt; void</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>sort</code></td><td><code>SortableSortDetails</code></td><td>顺序变化；detail 为 <code>{ from, to, id, ids }</code>，其中 ids 已重排好</td></tr><tr><td><code>drag-start</code></td><td><code>SortableDragStartDetails</code></td><td>拾起；detail 为 <code>{ id, from, mode }</code></td></tr><tr><td><code>drag-end</code></td><td><code>SortableDragEndDetails</code></td><td>收尾（含取消）；detail 为 <code>{ id, from, to, mode, canceled }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhSortableItem</code></td><td><code>default</code></td><td><code>SortableItemSlotProps</code></td><td></td></tr><tr><td><code>XhSortableItemHandle</code></td><td><code>default</code></td><td>—</td><td></td></tr><tr><td><code>XhSortableRoot</code></td><td><code>default</code></td><td><code>SortableRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code> · <code>pending</code> · <code>dragging</code></p><p><strong>事件</strong>：<code>ITEM.POINTER_DOWN</code> · <code>POINTER.MOVE</code> · <code>POINTER.END</code> · <code>POINTER.CANCEL</code> · <code>ITEM.PICKUP</code> · <code>KEY.MOVE</code> · <code>KEY.DROP</code> · <code>KEY.CANCEL</code></p><p><strong>判据</strong>：<code>canSort</code> · <code>passedActivation</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useSortable</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>dragging</code></td><td><code>boolean</code></td><td>正在拖（含键盘拖动）。</td></tr><tr><td><code>activeId</code></td><td><code>string | null</code></td><td></td></tr><tr><td><code>from</code></td><td><code>number</code></td><td></td></tr><tr><td><code>to</code></td><td><code>number</code></td><td></td></tr><tr><td><code>mode</code></td><td><code>SortableMode | null</code></td><td></td></tr><tr><td><code>items</code></td><td><code>SortableItemState[]</code></td><td>逐项的呈现状态，顺序与 <code>ids</code> 一致。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: SortableItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemHandleProps</code></td><td><code>(props: SortableItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLiveRegionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/practices/keyboard-interface/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Space</code> / <code>Enter</code></td><td>focus in item-handle，未在拖动，not disabled</td><td>拾起这一项，进入键盘拖动；播报它现在第几位、共几项、以及接下来能按什么</td></tr><tr><td><code>ArrowDown</code> / <code>ArrowRight</code></td><td>键盘拖动中</td><td>往后挪一位并播报新位置；已在末位时不动，也不回绕。竖直排布认上下键、水平排布认左右键，另一条轴上的方向键原样放行</td></tr><tr><td><code>ArrowUp</code> / <code>ArrowLeft</code></td><td>键盘拖动中</td><td>往前挪一位，规则同上；rtl 下左右两键对调，语义恒是「往前 / 往后」</td></tr><tr><td><code>Space</code> / <code>Enter</code></td><td>键盘拖动中</td><td>放下，按当前位置提交顺序并播报落点</td></tr><tr><td><code>Escape</code></td><td>键盘拖动中</td><td>取消，顺序回到拾起前，播报已取消与原位置</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-label</code></td><td>translations?.root</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>item-handle</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item-handle</code></td><td><code>aria-label</code></td><td>translations?.itemHandle?.(name)</td></tr><tr><td><code>item-handle</code></td><td><code>aria-pressed</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item-handle</code></td><td><code>aria-roledescription</code></td><td>&#39;sortable&#39;</td></tr><tr><td><code>item-handle</code></td><td><code>role</code></td><td>&#39;button&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr><tr><td><code>live-region</code></td><td><code>role</code></td><td>&#39;status&#39;</td></tr></tbody></table><ul><li>手柄是 <code>role=button</code>，带 <code>aria-roledescription=&quot;sortable&quot;</code> 与 <code>aria-pressed</code>。</li><li>拖动过程的每一步都写进视觉隐藏的 <code>role=status</code> 区域，读屏能听到「移到第几位，共几项」。</li><li>拖动中的 Tab 会被拦下：焦点一旦移走，这一场就没有出口了。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/sortable.css</code> 按部件选择：<code>[data-scope=&quot;sortable&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>item</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-index</code></td><td>String(item?.index ?? -1)</td></tr><tr><td><code>item-handle</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-sortable-gap</code> · <code>--xh-sortable-handle-bg-hover</code> · <code>--xh-sortable-handle-fg</code> · <code>--xh-sortable-handle-fg-disabled</code> · <code>--xh-sortable-handle-fg-hover</code> · <code>--xh-sortable-handle-radius</code> · <code>--xh-sortable-handle-size</code> · <code>--xh-sortable-item-opacity-dragging</code> · <code>--xh-sortable-item-shadow-dragging</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>每项里放一个拖拽手柄：只有手柄能拖，条目其余部分照常可点。</li><li>与<a href="./table">表格</a>的列设置配合，做成可拖的列顺序面板。</li></ul>',41))])}const q=i(h,[["render",p]]);export{S as __pageData,q as default};
